import type { SatForm, SatQuestion } from "./types";

/**
 * Practice Test 12 — a FULL-LENGTH adaptive digital-SAT form (original,
 * hand-verified items). Reading & Writing modules are 27 questions each;
 * Math modules are 22 questions each. Topics and passages are distinct from
 * Practice Tests 1–11. Every math answer key has been solved and checked.
 */

// ─────────────────────── PRACTICE TEST 12 · R&W M1 (27) ──────────────────────
const T12_RW_M1: SatQuestion[] = [
  { id: "t12rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The glassblower's technique was so ______ that apprentices spent years simply learning to hold the rod at the correct angle.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["exacting", "casual", "playful", "trivial"], correct: 0, explanation: "The blank describes a technique so demanding that apprentices need years just to master holding the rod correctly, so it must mean rigorous and precise. \"Exacting\" means requiring great care, effort, and accuracy, which matches the long training and the \"correct angle\" detail exactly. \"Casual\" means relaxed and informal, the opposite of a skill needing years of practice. \"Playful\" means lighthearted, which does not fit a serious, difficult craft. \"Trivial\" means unimportant or easy, directly contradicting the years of effort the sentence stresses." },
  { id: "t12rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The committee of advisers ______ scheduled to release its findings on Friday.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "have been", "were"], correct: 0, explanation: "Subject-verb agreement: the verb must agree with the true subject, not with a noun inside a prepositional phrase. The subject is the singular collective noun \"committee\"; \"of advisers\" is a prepositional phrase that cannot govern the verb. A singular subject takes the singular verb \"is,\" so A is correct. \"Are\" (B) and \"were\" (D) are plural and wrongly agree with the nearby plural \"advisers.\" \"Have been\" (C) is also plural and additionally shifts the tense away from the simple present the rest of the sentence uses." },
  { id: "t12rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Tardigrades, microscopic animals barely visible to the naked eye, can enter a dried-out state called cryptobiosis in which their metabolism nearly stops, letting them survive boiling heat, deep freezing, and even the vacuum of space.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["By nearly halting their metabolism, tardigrades can endure extreme conditions.", "Tardigrades are large animals that thrive only in mild climates.", "Tardigrades cannot survive any change in temperature.", "Tardigrades reproduce faster in the vacuum of space."], correct: 0, explanation: "The text's central claim is that by entering cryptobiosis, in which \"their metabolism nearly stops,\" tardigrades can \"survive boiling heat, deep freezing, and even the vacuum of space.\" Choice A captures exactly this link between the near-halt of metabolism and survival of extreme conditions. Choice B is wrong because the passage calls them \"microscopic animals barely visible to the naked eye,\" not large, and says they survive extremes, not only mild climates. Choice C contradicts the explicit list of temperature extremes they endure. Choice D introduces reproduction, a topic the passage never mentions, so it has no textual support." },
  { id: "t12rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The reservoir had dropped to record-low levels. ______, the city introduced strict limits on lawn watering.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "Consequently", "However", "In contrast"], correct: 1, explanation: "The first sentence gives a cause (the reservoir hit record lows) and the second gives its effect (the city imposed watering limits), so the transition must signal cause-and-effect. \"Consequently\" means \"as a result,\" which fits perfectly. \"Nevertheless\" (A) and \"However\" (C) signal contrast or concession, but there is no opposition here, only a logical result. \"In contrast\" (D) sets up a difference between two things, but the two sentences agree rather than contrast, so it fails the logic." },
  { id: "t12rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The kit contained everything we needed ______ a tent, a stove, and a water filter.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["needed, ", "needed: ", "needed; ", "needed "], correct: 1, explanation: "Rule: a colon introduces a list or explanation when a complete independent clause precedes it. \"The kit contained everything we needed\" is a complete sentence, and the items that follow specify \"everything,\" so the colon in B is correct. A comma (A) is too weak to introduce a formal list after a full clause. A semicolon (C) must join two independent clauses, but \"a tent, a stove, and a water filter\" is not an independent clause. No punctuation (D) runs the list directly into the clause without the needed separation." },
  { id: "t12rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her summary of the dense report was admirably ______, capturing the key findings in just two sentences.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["succinct", "rambling", "vague", "lengthy"], correct: 0, explanation: "The summary is praised (\"admirably\") for \"capturing the key findings in just two sentences,\" so the blank must mean brief yet complete. \"Succinct\" means expressed clearly in few words, matching both the brevity and the success. \"Rambling\" (B) means wandering and overlong, the opposite of two tight sentences. \"Vague\" (C) means unclear or imprecise, which contradicts \"capturing the key findings.\" \"Lengthy\" (D) means long, contradicting \"just two sentences.\"" },
  { id: "t12rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The fellowship is awarded only to artists who have completed at least one full-length public exhibition and who live within the state; out-of-state applicants are not considered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["An artist living outside the state cannot receive the fellowship.", "Any artist may receive the fellowship regardless of residence.", "The fellowship funds artists who have never exhibited.", "The fellowship is limited to musicians."], correct: 0, explanation: "The text sets two conditions and adds that \"out-of-state applicants are not considered.\" That last clause directly supports A: an artist living outside the state cannot receive the fellowship. Choice B contradicts the residency rule, since residence clearly does matter. Choice C contradicts the requirement of \"at least one full-length public exhibition,\" so an artist who never exhibited cannot qualify. Choice D restricts the award to musicians, but the text refers only to \"artists\" and never limits it to musicians." },
  { id: "t12rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The team spent months gathering field samples. ______, it built a custom database to organize the results.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "In addition", "Otherwise", "Instead"], correct: 1, explanation: "Both sentences describe steps the team took, and building a database is an additional task on top of gathering samples, so an additive transition is needed. \"In addition\" signals one more action in a sequence, fitting the logic. \"However\" (A) signals contrast, but the two steps do not oppose each other. \"Otherwise\" (C) introduces a consequence of not doing something, which is not the relationship here. \"Instead\" (D) signals replacement, implying the database replaced the gathering, but the text presents both as completed steps." },
  { id: "t12rw1-9", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Reviewers found the novel's plot ______, full of unexpected turns that kept them guessing until the final page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["suspenseful", "predictable", "dull", "tedious"], correct: 0, explanation: "The plot is \"full of unexpected turns that kept them guessing until the final page,\" so the blank must mean tense and gripping. \"Suspenseful\" means producing excited uncertainty about what happens next, exactly matching \"kept them guessing.\" \"Predictable\" (B) means easily foreseen, the direct opposite of \"unexpected turns.\" \"Dull\" (C) means boring, contradicting a plot that holds attention to the last page. \"Tedious\" (D) means tiresomely long or dull, again contradicting the engagement described." },
  { id: "t12rw1-10", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Bees communicate the location of food through a precise \"waggle dance,\" in which the angle and duration of the movement encode the direction and distance to a flower patch.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bees use a dance to convey where food can be found.", "Bees cannot share information with one another.", "Bees dance only for entertainment.", "Bees ignore the distance to food sources."], correct: 0, explanation: "The text says bees \"communicate the location of food\" through the waggle dance, whose \"angle and duration encode the direction and distance to a flower patch.\" Choice A restates this purpose of conveying where food is. Choice B contradicts the explicit fact that bees communicate. Choice C says the dance is only for entertainment, but the text states a clear informational purpose. Choice D claims bees ignore distance, yet the passage says duration encodes distance." },
  { id: "t12rw1-11", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Neither the manager nor the employees ______ aware of the schedule change until that morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "is", "were", "has been"], correct: 2, explanation: "Rule of proximity for \"neither...nor\": the verb agrees with the subject nearer to it. Here the nearer subject is the plural \"employees,\" so the verb must be plural. \"Were\" (C) is the correct plural past-tense form and matches the past-time context (\"until that morning\"). \"Was\" (A) and \"has been\" (D) are singular and would agree only with the farther subject \"manager.\" \"Is\" (B) is singular and also wrongly shifts to present tense, conflicting with the past-tense narration." },
  { id: "t12rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The first prototype overheated within minutes. ______, the engineers gained crucial data that guided a far more reliable design.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Still", "For instance", "Therefore", "In short"], correct: 0, explanation: "The prototype \"overheated within minutes\" (a setback), yet the engineers \"gained crucial data\" (a benefit), so the transition must signal contrast or concession. \"Still\" means \"nevertheless,\" capturing that something good came despite the failure. \"For instance\" (B) introduces an example, but the data is not an example of overheating. \"Therefore\" (C) signals a result, wrongly implying the failure caused the data in a straightforward way rather than despite it. \"In short\" (D) introduces a summary, but the second sentence adds new information rather than summarizing." },
  { id: "t12rw1-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A regional study reported recycling rates of 41% in the north, 58% in the central zone, and 63% in the south.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The recycling rate was lowest in the north.", "The recycling rate was highest in the north.", "The central zone had the highest recycling rate.", "All three zones recycled at the same rate."], correct: 0, explanation: "The three reported rates are north 41%, central 58%, and south 63%. The smallest figure is 41% in the north, so A correctly identifies the north as lowest. Choice B reverses this; 41% is the lowest, not the highest. Choice C names the central zone (58%) as highest, but the south's 63% is higher. Choice D claims all three are equal, which the distinct percentages contradict." },
  { id: "t12rw1-14", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The archive holds a manuscript ______ pages had survived a fire that destroyed most of the library.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["whose", "who's", "that", "which"], correct: 0, explanation: "The blank needs a possessive relative pronoun to show that the \"pages\" belong to the \"manuscript.\" \"Whose\" is the possessive relative pronoun and can refer to a thing as well as a person, so A is correct. \"Who's\" (B) is a contraction of \"who is\" and cannot show possession. \"That\" (C) and \"which\" (D) are relative pronouns that introduce clauses but cannot stand in for a possessive, so \"that pages had survived\" leaves no owner for the pages." },
  { id: "t12rw1-15", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Rushing to catch the ferry, ______ the heavy suitcase slowed the traveler to a frustrating crawl.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["rushing to catch the ferry, the heavy suitcase slowed the traveler", "the traveler, rushing to catch the ferry, was slowed by the heavy suitcase", "the heavy suitcase, rushing to catch the ferry, slowed the traveler", "rushed, the suitcase slowed the traveler to the ferry"], correct: 1, explanation: "Rule: an introductory participial phrase must modify the noun that immediately follows it. \"Rushing to catch the ferry\" describes a person, so the traveler must come right after the comma. Only B does this: \"the traveler, rushing to catch the ferry, was slowed by the heavy suitcase.\" Choices A and C place \"the heavy suitcase\" right after the modifier, illogically saying the suitcase was rushing. Choice D's \"rushed, the suitcase\" again makes the suitcase the thing rushing and is also awkward and unclear." },
  { id: "t12rw1-16", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers propose that brief afternoon naps improve memory because sleep helps the brain consolidate newly learned information.", prompt: "Which finding, if true, would most strengthen the researchers' claim?", type: "mcq", choices: ["Students who napped after studying recalled more material than those who stayed awake.", "Most people enjoy taking afternoon naps.", "Naps are more common in warm climates.", "People who nap tend to wake up groggy."], correct: 0, explanation: "The claim is that afternoon naps improve memory by helping the brain consolidate new information, so the strongest support is direct evidence of better memory after napping. Choice A provides exactly this: students who napped after studying \"recalled more material\" than those who stayed awake, linking napping to improved memory. Choice B concerns enjoyment of naps, which says nothing about memory. Choice C concerns where naps are common, again irrelevant to memory. Choice D notes a drawback (grogginess), which would weaken rather than strengthen the memory claim." },
  { id: "t12rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The director, together with the lead actors, ______ attending the festival next week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "were", "have been"], correct: 0, explanation: "Subject-verb agreement rule: a phrase set off by commas with \"together with\" is parenthetical and does not change the number of the subject. The true subject is the singular \"director,\" so the singular present-tense verb \"is\" is correct (A). \"Are\" (B) is plural and wrongly agrees with the nearby \"actors\" rather than the real subject. \"Were\" (C) is plural and also shifts to past tense, conflicting with the future sense of \"next week.\" \"Have been\" (D) is plural and likewise mismatches the singular subject while adding an unneeded perfect aspect." },
  { id: "t12rw1-18", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "A researcher wants to underscore that two independent labs reached the same surprising result. ______, both teams measured the reaction rate as identical to three decimal places.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["By contrast", "Remarkably", "However", "Otherwise"], correct: 1, explanation: "The researcher wants to underscore a surprising agreement between two labs, so the transition must emphasize how striking the match is. \"Remarkably\" (B) means \"surprisingly\" and spotlights the notable result, matching the goal exactly. \"By contrast\" (A) signals a difference between two things, but the two labs agree rather than differ. \"However\" (C) signals opposition or concession, which contradicts the emphasis on agreement. \"Otherwise\" (D) introduces an alternative or what would happen if something were not true, a relationship absent here." },
  { id: "t12rw1-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The essay's tone is deliberately ______: it never tells readers what to feel, instead laying out competing evidence and leaving the verdict to them.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["impartial", "biased", "sentimental", "hostile"], correct: 0, explanation: "The essay \"never tells readers what to feel\" and instead lays out \"competing evidence,\" leaving the verdict to readers, so the blank must mean even-handed and neutral. \"Impartial\" (A) means not favoring one side, exactly matching the refusal to push a conclusion. \"Biased\" (B) means favoring one side, the direct opposite of presenting competing evidence neutrally. \"Sentimental\" (C) means driven by emotion, but the essay deliberately avoids telling readers what to feel. \"Hostile\" (D) means antagonistic, which has no basis in an essay that withholds judgment." },
  { id: "t12rw1-20", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The rebate is offered only to drivers who purchased an electric vehicle after January 2024 and who registered it in the city.", prompt: "Which driver clearly qualifies for the rebate?", type: "mcq", choices: ["A driver who bought an electric vehicle in 2024 and registered it in the city.", "A driver who bought a gasoline vehicle in 2024 and registered it in the city.", "A driver who bought an electric vehicle in 2020 and registered it in the city.", "A driver who has never purchased a vehicle."], correct: 0, explanation: "The rebate requires two things: an electric vehicle purchased after January 2024 AND city registration. Choice A satisfies both, an electric vehicle bought in 2024 and registered in the city, so it clearly qualifies. Choice B fails the vehicle-type requirement because a gasoline vehicle is not electric. Choice C fails the date requirement because a 2020 purchase predates January 2024. Choice D fails both requirements because the driver never purchased any vehicle at all." },
  { id: "t12rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The crew repaired the dam ______ they reinforced the levees downstream.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["dam, and then", "dam and, then", "dam then", "dam, then"], correct: 0, explanation: "Rule: two independent clauses are correctly joined by a comma plus a coordinating conjunction (FANBOYS). \"The crew repaired the dam\" and \"they reinforced the levees downstream\" are both complete clauses, so \"dam, and then\" (A) joins them correctly. \"Dam, then\" (D) puts only a comma between two clauses, creating a comma splice. \"Dam then\" (C) has no punctuation or conjunction, creating a run-on. \"Dam and, then\" (B) keeps the conjunction but misplaces the comma after \"and,\" which is never correct." },
  { id: "t12rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Although usually ______ in public, the scientist spoke with surprising warmth when describing her students' work.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["reserved", "outgoing", "boastful", "talkative"], correct: 0, explanation: "The word \"Although\" sets up a contrast with her \"surprising warmth,\" so her usual public manner must be the opposite of warm and open, that is, restrained. \"Reserved\" (A) means restrained and undemonstrative, which contrasts properly with the unexpected warmth. \"Outgoing\" (B) means sociable and warm, so it would not contrast with warmth and breaks the \"although\" logic. \"Boastful\" (C) means given to bragging, which is neither a clear opposite of warmth nor supported by the sentence. \"Talkative\" (D) means inclined to talk a lot, which also fails to contrast with warmth." },
  { id: "t12rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "An economist observes that towns that built train stations in the 1800s tend to have larger downtowns today, crediting the early access to markets and labor.", prompt: "Which choice best describes the economist's explanation?", type: "mcq", choices: ["Early rail access boosted markets and labor, producing larger downtowns.", "Train stations shrank the towns that built them.", "Downtown size is unrelated to rail history.", "Towns without stations grew the most."], correct: 0, explanation: "The economist observes that early-station towns \"tend to have larger downtowns today\" and credits this to \"early access to markets and labor,\" which choice A restates as a cause producing larger downtowns. Choice B reverses the effect, claiming stations \"shrank\" towns, the opposite of larger downtowns. Choice C says downtown size is \"unrelated to rail history,\" contradicting the very link the economist draws. Choice D claims stationless towns grew most, but the text says the opposite, that towns WITH early stations have larger downtowns." },
  { id: "t12rw1-24", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The board delayed the vote ______ it still lacked the budget figures from two departments.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["vote because", "vote, because", "vote; because", "vote: because"], correct: 0, explanation: "Rule: when a \"because\" clause follows the main clause and gives essential information, no punctuation separates them. \"The board delayed the vote\" is followed by the essential reason \"because it still lacked the budget figures,\" so \"vote because\" (A) is correct. A comma (B) is unnecessary and wrongly breaks an essential adverbial clause. A semicolon (C) must join two independent clauses, but \"because it still lacked...\" is dependent, not independent. A colon (D) must follow a complete clause and introduce a list or explanation set off formally, which does not fit a simple \"because\" reason." },
  { id: "t12rw1-25", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory switched to recycled materials. ______, it lowered its raw-material costs by nearly a third.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["As a result", "Nevertheless", "For example", "On the other hand"], correct: 0, explanation: "The first sentence gives a cause (switching to recycled materials) and the second gives its effect (raw-material costs dropped by a third), so a cause-effect transition is needed. \"As a result\" (A) means \"consequently\" and fits the cause-effect link exactly. \"Nevertheless\" (B) signals concession or contrast, but the two sentences agree rather than oppose. \"For example\" (C) introduces an illustration, but lower costs are an outcome, not an instance, of the switch. \"On the other hand\" (D) signals a contrasting point, which the logical result does not provide." },
  { id: "t12rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The coach offered ______ feedback, pointing to exactly which footwork each player should adjust.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["specific", "vague", "general", "confusing"], correct: 0, explanation: "The coach points \"to exactly which footwork each player should adjust,\" so the feedback is precise and detailed. \"Specific\" (A) means clearly defined and particular, matching the exact, targeted guidance. \"Vague\" (B) means unclear and imprecise, the opposite of pointing to exactly what to fix. \"General\" (C) means broad rather than particular, contradicting the pinpointed footwork. \"Confusing\" (D) means hard to understand, which clashes with feedback a player can act on directly." },
  { id: "t12rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A long-term study found that removing an invasive grass from a marsh allowed native sedges to return, which in turn drew back the wading birds that had abandoned the wetland years earlier.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Removing the invasive grass set off a chain of recoveries that brought birds back.", "The invasive grass had no effect on the marsh.", "Wading birds drove the sedges out of the marsh.", "Native sedges declined after the grass was removed."], correct: 0, explanation: "The text describes a sequence: removing the invasive grass \"allowed native sedges to return, which in turn drew back the wading birds,\" so the main idea is a chain of recoveries triggered by the removal, which choice A captures. Choice B says the grass \"had no effect,\" contradicting the documented chain of effects. Choice C claims the birds \"drove the sedges out,\" reversing the cause and effect, since the sedges returned and then attracted the birds. Choice D says sedges \"declined after\" removal, contradicting the text's statement that the sedges returned." },
];

// ─────────────────────── PRACTICE TEST 12 · R&W M2 easy (27) ─────────────────
const T12_RW_M2E: SatQuestion[] = [
  { id: "t12rw2e-1", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The lemonade was too ______, so she added a spoonful of sugar.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["sour", "sweet", "tall", "green"], correct: 0, explanation: "She fixes the lemonade by \"adding a spoonful of sugar,\" and sugar reduces sourness, so the drink must have been too \"sour.\" Choice A, \"sour,\" is the problem sugar solves, so it fits. Choice B, \"sweet,\" is the opposite problem; adding more sugar would make it worse, not better. Choice C, \"tall,\" describes height, not taste, so it is illogical for lemonade. Choice D, \"green,\" describes color and is not something sugar would fix." },
  { id: "t12rw2e-2", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The three puppies ______ playing in the yard.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Subject-verb agreement: the verb must match the number of the subject. \"The three puppies\" is plural, so it needs the plural verb \"are\" (B). \"Is\" (A) is singular and cannot agree with a plural subject. \"Was\" (C) is singular and also shifts to past tense, while the action \"playing\" is ongoing. \"Am\" (D) is the first-person singular form used only with \"I,\" so it never agrees with \"puppies.\"" },
  { id: "t12rw2e-3", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Bats are not blind; many use sound echoes to find insects in the dark.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Bats can locate food using sound, not just sight.", "Bats cannot find food at all.", "Bats only hunt during the day.", "Bats have no sense of hearing."], correct: 0, explanation: "The text says bats \"are not blind\" and \"many use sound echoes to find insects in the dark,\" so the main idea is that bats locate food by sound as well as sight, which choice A states. Choice B says bats \"cannot find food at all,\" contradicting that they find insects. Choice C says bats hunt \"only during the day,\" but the text says they find insects \"in the dark.\" Choice D says bats have \"no sense of hearing,\" contradicting their use of sound echoes." },
  { id: "t12rw2e-4", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The movie was about to start. ______, we hurried to our seats.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "So", "However", "Meanwhile"], correct: 1, explanation: "The movie was about to start (cause) and the people hurried to their seats (effect), so a cause-effect transition is needed. \"So\" (B) means \"therefore\" and fits this result. \"However\" (A) signals contrast, but hurrying agrees with, not opposes, the movie starting. \"For example\" (C) introduces an illustration, but hurrying is an outcome, not an example. \"Meanwhile\" (D) signals a separate event happening at the same time, not a consequence." },
  { id: "t12rw2e-5", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Yesterday they ______ a sandcastle on the beach.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["build", "builds", "built", "building"], correct: 2, explanation: "Verb tense rule: the time marker \"Yesterday\" signals completed past action, so the simple past \"built\" (C) is correct. \"Build\" (A) is present tense and clashes with \"yesterday.\" \"Builds\" (B) is present tense and also singular, mismatching the plural \"they.\" \"Building\" (D) is a present participle that cannot serve as the main verb without a helping verb like \"were.\"" },
  { id: "t12rw2e-6", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The new sofa was so ______ that everyone wanted to sit on it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["comfortable", "broken", "wet", "loud"], correct: 0, explanation: "\"Everyone wanted to sit on it,\" so the sofa must have an inviting quality. \"Comfortable\" (A) explains why people want to sit, so it fits. \"Broken\" (B) would discourage sitting, not invite it. \"Wet\" (C) would also keep people from sitting. \"Loud\" (D) describes sound, not a reason to sit on a sofa, so it is illogical." },
  { id: "t12rw2e-7", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Walking to school saves money, gives good exercise, and reduces traffic.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Walking to school has several benefits.", "Walking to school is dangerous.", "Walking to school only saves money.", "Walking to school causes more traffic."], correct: 0, explanation: "The text lists three advantages of walking to school: it \"saves money, gives good exercise, and reduces traffic,\" so the main idea is that walking has several benefits, which choice A summarizes. Choice B says walking is \"dangerous,\" a claim the text never makes. Choice C says it \"only saves money,\" naming just one of the three benefits and ignoring the others. Choice D says walking \"causes more traffic,\" contradicting the stated benefit that it reduces traffic." },
  { id: "t12rw2e-8", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "He ate ______ apple before the game.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "Article rule: use \"an\" before a word beginning with a vowel sound. \"Apple\" starts with the vowel sound /a/, so \"an\" (B) is correct. \"A\" (A) is used only before consonant sounds, so \"a apple\" is wrong. \"The most\" (C) is a superlative phrase that does not fit a single apple. \"Some\" (D) implies an unspecified quantity, which clashes with the single countable \"apple.\"" },
  { id: "t12rw2e-9", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The directions were ______, so we reached the cabin without getting lost.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["clear", "confusing", "wrong", "missing"], correct: 0, explanation: "The travelers \"reached the cabin without getting lost,\" so the directions must have been easy to follow. \"Clear\" (A) means easy to understand, which explains the successful trip. \"Confusing\" (B) would more likely cause getting lost, the opposite result. \"Wrong\" (C) directions would also lead them astray, not to the cabin. \"Missing\" (D) directions could not guide them at all, contradicting the successful arrival." },
  { id: "t12rw2e-10", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "My cousin and I ______ baking cookies this afternoon.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Rule: a compound subject joined by \"and\" is plural and takes a plural verb. \"My cousin and I\" names two people, so the plural \"are\" (B) is correct. \"Is\" (A) is singular and cannot agree with a two-part subject. \"Was\" (C) is singular and also shifts to past tense, while \"this afternoon\" with \"baking\" describes ongoing action. \"Am\" (D) goes only with \"I\" alone, not with \"my cousin and I.\"" },
  { id: "t12rw2e-11", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Trees give off oxygen, provide shade, and offer homes for birds.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Trees are useful in several ways.", "Trees are harmful to birds.", "Trees provide no shade.", "Trees give off no oxygen."], correct: 0, explanation: "The text lists three useful roles of trees: they \"give off oxygen, provide shade, and offer homes for birds,\" so the main idea is that trees are useful in several ways, which choice A summarizes. Choice B says trees are \"harmful to birds,\" contradicting that they offer homes for birds. Choice C says trees \"provide no shade,\" contradicting the stated shade benefit. Choice D says trees \"give off no oxygen,\" contradicting the oxygen benefit." },
  { id: "t12rw2e-12", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The power went out during the storm. ______, we lit candles to see.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "As a result", "For example", "Instead"], correct: 1, explanation: "The power going out (cause) leads to lighting candles (effect), so a cause-effect transition is needed. \"As a result\" (B) signals this consequence and fits. \"However\" (A) signals contrast, but lighting candles agrees with, rather than opposes, losing power. \"For example\" (C) introduces an illustration, but the candles are an outcome, not an instance, of the outage. \"Instead\" (D) signals replacement, but nothing is being replaced here." },
  { id: "t12rw2e-13", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Last night the choir ______ a new song for the first time.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sing", "sings", "sang", "singing"], correct: 2, explanation: "Verb tense rule: the time marker \"Last night\" signals completed past action, so the simple past \"sang\" (C) is correct. \"Sing\" (A) is present tense and clashes with the past-time marker. \"Sings\" (B) is present tense and also singular, mismatching a past-time clause. \"Singing\" (D) is a present participle that needs a helping verb and cannot serve as the main verb alone." },
  { id: "t12rw2e-14", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "After hiking all day, the campers were ______ and fell asleep quickly.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["tired", "awake", "hungry", "excited"], correct: 0, explanation: "The campers \"fell asleep quickly\" after hiking all day, so they must have been worn out. \"Tired\" (A) explains falling asleep fast, so it fits. \"Awake\" (B) is the opposite of falling asleep and contradicts the result. \"Excited\" (C) would tend to keep them up rather than help them sleep. \"Hungry\" (D) describes a need for food and does not explain quick sleep after a hike." },
  { id: "t12rw2e-15", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "The pool is open from May to September but closes for the winter.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["The pool is closed in January.", "The pool is open all year.", "The pool never opens.", "The pool closes in summer."], correct: 0, explanation: "The pool is open \"from May to September\" but \"closes for the winter,\" and January is a winter month, so it is closed then, supporting choice A. Choice B says the pool is \"open all year,\" contradicting the winter closure. Choice C says it \"never opens,\" contradicting the May-to-September open season. Choice D places the closure \"in summer,\" but summer falls within the May-to-September open period, so this is wrong." },
  { id: "t12rw2e-16", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cat licked ______ paws after eating.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["its", "it's", "their", "they're"], correct: 0, explanation: "Possessive rule: \"its\" (no apostrophe) is the possessive form showing something belongs to a singular thing. The paws belong to the singular \"cat,\" so \"its\" (A) is correct. \"It's\" (B) is the contraction of \"it is\" and cannot show possession. \"Their\" (C) is a plural possessive, mismatching the single cat. \"They're\" (D) is the contraction of \"they are\" and is both plural and not possessive." },
  { id: "t12rw2e-17", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "Some animals sleep through winter. ______, bears hibernate in their dens for months.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["For example", "However", "Instead", "Otherwise"], correct: 0, explanation: "The first sentence makes a general claim (some animals sleep through winter) and the second gives a specific case (bears hibernate for months), so an illustrating transition is needed. \"For example\" (A) introduces that specific case and fits. \"However\" (B) signals contrast, but the bear case supports rather than opposes the claim. \"Instead\" (C) signals replacement, which does not fit an illustration. \"Otherwise\" (D) introduces an alternative condition, not an example." },
  { id: "t12rw2e-18", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The backpack was so ______ that she could barely lift it.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["heavy", "light", "soft", "quiet"], correct: 0, explanation: "She \"could barely lift it,\" so the backpack must have great weight. \"Heavy\" (A) explains why lifting was hard, so it fits. \"Light\" (B) is the opposite and would make lifting easy, contradicting the sentence. \"Soft\" (C) describes texture, not weight, so it does not explain the difficulty. \"Quiet\" (D) describes sound and has nothing to do with lifting." },
  { id: "t12rw2e-19", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "The cups ______ drying on the rack by the sink.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["is", "are", "was", "am"], correct: 1, explanation: "Subject-verb agreement: the verb must match the plural subject \"cups,\" so the plural \"are\" (B) is correct. \"Is\" (A) is singular and cannot agree with a plural subject. \"Was\" (C) is singular and also shifts to past tense, while \"drying\" describes ongoing action. \"Am\" (D) is used only with \"I\" and never agrees with \"cups.\"" },
  { id: "t12rw2e-20", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Salt was once so valuable that workers were sometimes paid with it.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Salt was highly valued in the past.", "Salt has always been worthless.", "Salt cannot be used as payment.", "Salt is harmful to workers."], correct: 0, explanation: "The text says salt was \"so valuable that workers were sometimes paid with it,\" so the main idea is that salt was highly valued in the past, which choice A states. Choice B says salt has \"always been worthless,\" contradicting its stated value. Choice C says salt \"cannot be used as payment,\" contradicting that workers were paid with it. Choice D says salt is \"harmful to workers,\" a claim the text never makes." },
  { id: "t12rw2e-21", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "We planned to picnic outside. ______, it began to rain.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["However", "Therefore", "For example", "Similarly"], correct: 0, explanation: "The plan to picnic outside is blocked by the rain, an unexpected reversal, so a contrast transition is needed. \"However\" (A) signals that contrast and fits. \"Therefore\" (B) signals a result, but rain does not result from planning a picnic. \"For example\" (C) introduces an illustration, but rain is not an example of the plan. \"Similarly\" (D) signals agreement, the opposite of the contrast between plan and rain." },
  { id: "t12rw2e-22", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "Next month the club ______ to host a fundraiser.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["plan", "plans", "planned", "planning"], correct: 1, explanation: "The collective noun \"club\" is treated as singular here, so it takes the singular verb \"plans\" (B); the present tense correctly expresses a scheduled future action signaled by \"next month.\" \"Plan\" (A) is the plural form and does not agree with the singular \"club.\" \"Planned\" (C) is past tense and clashes with the future \"next month.\" \"Planning\" (D) is a participle that cannot serve as the main verb without a helping verb." },
  { id: "t12rw2e-23", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The river was very ______ after the heavy rain, rushing past the banks.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["fast", "slow", "dry", "empty"], correct: 0, explanation: "The river was \"rushing past the banks\" after heavy rain, so it must have been moving quickly. \"Fast\" (A) matches rushing water, so it fits. \"Slow\" (B) is the opposite of rushing and contradicts the description. \"Dry\" (C) contradicts a river full of water after heavy rain. \"Empty\" (D) also contradicts a river that is rushing past its banks." },
  { id: "t12rw2e-24", section: "rw", domain: "Information and Ideas", difficulty: "easy", passage: "Brushing your teeth removes food, prevents cavities, and keeps breath fresh.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Brushing teeth has several benefits.", "Brushing teeth causes cavities.", "Brushing teeth only removes food.", "Brushing teeth harms the gums."], correct: 0, explanation: "The text lists three benefits of brushing: it \"removes food, prevents cavities, and keeps breath fresh,\" so the main idea is that brushing has several benefits, which choice A summarizes. Choice B says brushing \"causes cavities,\" contradicting that it prevents them. Choice C says brushing \"only removes food,\" naming just one benefit and ignoring the others. Choice D says brushing \"harms the gums,\" a claim the text never makes." },
  { id: "t12rw2e-25", section: "rw", domain: "Standard English Conventions", difficulty: "easy", passage: "She wore ______ orange scarf to the parade.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["a", "an", "the most", "some"], correct: 1, explanation: "Article rule: use \"an\" before a word beginning with a vowel sound. \"Orange\" starts with the vowel sound /o/, so \"an\" (B) is correct. \"A\" (A) is used only before consonant sounds, making \"a orange\" wrong. \"The most\" (C) is a superlative that does not fit a single scarf. \"Some\" (D) implies an unspecified amount, clashing with the single countable \"scarf.\"" },
  { id: "t12rw2e-26", section: "rw", domain: "Expression of Ideas", difficulty: "easy", passage: "The cake was easy to make. ______, it tasted delicious.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In addition", "However", "Instead", "Otherwise"], correct: 0, explanation: "The first sentence gives one good point (easy to make) and the second adds another (tasted delicious), so an additive transition is needed. \"In addition\" (A) signals one more point and fits. \"However\" (B) signals contrast, but the two good points agree rather than oppose. \"Instead\" (C) signals replacement, but neither point replaces the other. \"Otherwise\" (D) introduces an alternative condition, not an added point." },
  { id: "t12rw2e-27", section: "rw", domain: "Craft and Structure", difficulty: "easy", passage: "The audience was ______ when the magician made the rabbit disappear.", prompt: "Which choice completes the text with the most logical word?", type: "mcq", choices: ["amazed", "bored", "asleep", "angry"], correct: 0, explanation: "Seeing a magician make a rabbit disappear is a surprising spectacle, so the audience would feel wonder. \"Amazed\" (A) captures that wonder and fits. \"Bored\" (B) contradicts the excitement of a surprising trick. \"Asleep\" (C) is impossible for an audience reacting to a vanishing rabbit. \"Angry\" (D) is an unsupported emotion that a magic trick would not normally produce." },
];

// ─────────────────────── PRACTICE TEST 12 · R&W M2 hard (27) ─────────────────
const T12_RW_M2H: SatQuestion[] = [
  { id: "t12rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The minister's statement was so ______ that supporters and critics alike claimed it endorsed their opposing positions.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["ambiguous", "explicit", "blunt", "candid"], correct: 0, explanation: "If \"supporters and critics alike claimed it endorsed their opposing positions,\" the statement must be open to multiple readings. \"Ambiguous\" (A) means open to more than one interpretation, exactly why both camps could claim it. \"Explicit\" (B) means stated clearly and in full, which would leave no room for opposing readings. \"Blunt\" (C) means direct and plain-spoken, again too clear to be read two ways. \"Candid\" (D) means frank and open, which likewise would not allow contradictory interpretations." },
  { id: "t12rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The chapter opens by tracing a single river's path from glacier to delta before widening, in its closing pages, into a general theory of how all great rivers shape civilizations.", prompt: "Which choice best describes the structure of the text?", type: "mcq", choices: ["It moves from one detailed case to a broad generalization.", "It begins with a theory and offers no examples.", "It lists rivers without analysis.", "It repeats the same river description throughout."], correct: 0, explanation: "The chapter \"opens by tracing a single river's path\" (a detailed case) before \"widening... into a general theory of how all great rivers shape civilizations\" (a generalization), a specific-to-general movement captured by choice A. Choice B says it \"begins with a theory and offers no examples,\" reversing the order, since it begins with one detailed river. Choice C says it \"lists rivers without analysis,\" ignoring the broad theory it builds. Choice D says it \"repeats the same river description,\" contradicting the widening into a general theory." },
  { id: "t12rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A solar panel produced 98% of its rated output in year 1, 96% in year 5, and 82% in year 20.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Output declined more sharply between years 5 and 20 than between years 1 and 5.", "Output rose as the panel aged.", "Output stayed exactly constant.", "The panel produced nothing by year 5."], correct: 0, explanation: "The data show 98% at year 1, 96% at year 5, and 82% at year 20, so output fell 2 points across years 1-5 but 14 points across years 5-20, a sharper later decline, supporting choice A. Choice B says output \"rose as the panel aged,\" reversing the clear downward trend. Choice C says output \"stayed exactly constant,\" contradicting the falling percentages. Choice D says the panel \"produced nothing by year 5,\" contradicting the 96% reading at year 5." },
  { id: "t12rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new rail line would slash cross-town travel time. ______, it would require demolishing a historic market that has stood for two centuries.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "The first sentence states a benefit (the rail line would slash travel time) and the second states a serious drawback (it would demolish a two-century-old market), so a contrast transition is needed. \"However\" (B) signals that opposition and fits. \"Therefore\" (A) marks a result, but demolition is not a consequence of faster travel. \"Likewise\" (C) marks similarity, the opposite of a benefit set against a cost. \"Accordingly\" (D) also marks a result and fails the same way as \"Therefore.\"" },
  { id: "t12rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The program teaches students to analyze data, to write reports, and ______ findings to a live audience.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["to present", "presenting", "present", "presented"], correct: 0, explanation: "Parallel-structure rule: items in a series must share the same grammatical form. The series uses two infinitives, \"to analyze data\" and \"to write reports,\" so the third item must also be an infinitive, \"to present\" (A). \"Presenting\" (B) is a gerund, breaking the infinitive pattern. \"Present\" (C) is a bare verb that does not match the \"to + verb\" form of the other items. \"Presented\" (D) is a past participle, again inconsistent with the parallel infinitives." },
  { id: "t12rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir refuses to ______ its author's youth, presenting his reckless mistakes as frankly as his hard-won wisdom.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["romanticize", "condemn", "narrate", "recall"], correct: 0, explanation: "The memoir presents \"reckless mistakes as frankly as his hard-won wisdom,\" refusing to dress up the past, so the blank must mean to idealize. \"Romanticize\" (A) means to make something seem better or more appealing than it was, exactly what frank honesty refuses to do. \"Condemn\" (B) means to denounce harshly, the opposite extreme, and the memoir is balanced, not harsh. \"Narrate\" (C) merely means to tell, which the memoir clearly does rather than refuses to do. \"Recall\" (D) means to remember, again something the memoir does, not something it refuses." },
  { id: "t12rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Where the traditional account treats language change as decay from a pure original form, the newer model views it as a natural, ongoing process of adaptation.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast an older view of language change with a newer one.", "To prove language never changes.", "To summarize only the traditional account.", "To argue that language has no rules."], correct: 0, explanation: "The structure \"Where the traditional account treats... the newer model views...\" sets two opposing views of language change side by side, so the purpose is to contrast them, which choice A captures. Choice B says the text proves \"language never changes,\" but both views agree change happens; they only disagree on how to judge it. Choice C says it summarizes \"only the traditional account,\" ignoring the newer model the text also presents. Choice D says it argues \"language has no rules,\" an overstatement the text never makes." },
  { id: "t12rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The day shift cleared the backlog of orders by noon ______ the night shift was still sorting the same pile at dawn.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["noon, the", "noon; the", "noon the", "noon: the"], correct: 1, explanation: "Rule: two independent clauses with no coordinating conjunction must be joined by a semicolon. \"The day shift cleared the backlog of orders by noon\" and \"the night shift was still sorting the same pile at dawn\" are both complete clauses, so \"noon; the\" (B) is correct. \"Noon, the\" (A) uses only a comma, creating a comma splice. \"Noon the\" (C) has no punctuation at all, creating a run-on. \"Noon: the\" (D) uses a colon, which wrongly signals that a list or explanation follows rather than a contrasting independent clause." },
  { id: "t12rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the lecture was packed with technical terms that even specialists had to pause and decode.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["accessible", "dense", "technical", "challenging"], correct: 0, explanation: "The phrase \"Far from being ___\" signals that the blank is the OPPOSITE of what the lecture actually was; since the lecture was \"packed with technical terms that even specialists had to pause and decode,\" it was difficult, so the blank must be the opposite, easy to understand. \"Accessible\" (A) means easy to understand, which the difficult lecture was far from, so it fits the reversal. \"Dense\" (B) means hard to follow, which matches rather than opposes the difficulty, breaking the \"far from\" logic. \"Technical\" (C) likewise matches the jargon-filled lecture instead of opposing it. \"Challenging\" (D) also describes the difficulty itself, not its opposite, so it fails the reversal." },
  { id: "t12rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Advocates insist the new fishing rules protected stocks without hurting local fleets. Yet in the rules' first season, the number of active boats fell by 12%.", prompt: "Which choice best describes the function of the second sentence?", type: "mcq", choices: ["It presents evidence that complicates the advocates' claim.", "It restates the advocates' claim exactly.", "It confirms that fleets were unaffected.", "It proposes an entirely new rule."], correct: 0, explanation: "The first sentence gives the advocates' claim that the rules \"protected stocks without hurting local fleets\"; the second, beginning with \"Yet,\" reports that active boats \"fell by 12%,\" which complicates that claim, making choice A correct. Choice B says the sentence \"restates the advocates' claim exactly,\" but \"Yet\" introduces opposing evidence, not a restatement. Choice C says it \"confirms that fleets were unaffected,\" the opposite of a 12% drop in boats. Choice D says it \"proposes an entirely new rule,\" but the sentence reports a result, not a proposal." },
  { id: "t12rw2h-11", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The proposal rested on three pillars ______ stable funding, trained staff, and community support.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["pillars,", "pillars:", "pillars;", "pillars"], correct: 1, explanation: "Rule: a colon introduces a list when a complete independent clause precedes it. \"The proposal rested on three pillars\" is a complete clause, and the items name those pillars, so \"pillars:\" (B) is correct. A comma (A) is too weak to introduce a formal list after a full clause. A semicolon (C) must join two independent clauses, but \"stable funding, trained staff, and community support\" is not a clause. No punctuation (D) leaves the list running into the clause with no separation." },
  { id: "t12rw2h-12", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The algorithm sorted the familiar images flawlessly. ______, it stumbled badly on photographs taken in unusual lighting.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Indeed", "Nonetheless", "Therefore", "Likewise"], correct: 1, explanation: "The algorithm \"sorted the familiar images flawlessly\" (success) but \"stumbled badly\" on unusual lighting (failure), so a concessive contrast transition is needed. \"Nonetheless\" (B) means \"in spite of that\" and signals the shift to failure. \"Indeed\" (A) reinforces a prior point, but failure does not reinforce success. \"Therefore\" (C) marks a result, yet the failure is not caused by the success. \"Likewise\" (D) marks similarity, the opposite of the contrast between flawless and stumbling." },
  { id: "t12rw2h-13", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a trial, the new coating made the lenses 40% more scratch-resistant but also reduced their light transmission by 15%.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The coating improved scratch resistance but reduced light transmission.", "The coating improved both scratch resistance and light transmission.", "The coating had no measurable effect.", "Uncoated lenses were more scratch-resistant."], correct: 0, explanation: "The text reports the coating made lenses \"40% more scratch-resistant but also reduced their light transmission by 15%,\" a clear trade-off captured by choice A. Choice B says it improved \"both scratch resistance and light transmission,\" ignoring that transmission dropped. Choice C says it had \"no measurable effect,\" contradicting both reported changes. Choice D says \"uncoated lenses were more scratch-resistant,\" reversing the result that the coating improved scratch resistance." },
  { id: "t12rw2h-14", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The sculpture that stands at the center of the plaza ______ from a single block of marble quarried nearby.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["come", "comes", "coming", "to come"], correct: 1, explanation: "Subject-verb agreement: the verb agrees with the true subject, not with a noun in an intervening modifier. The subject is the singular \"sculpture\"; \"that stands at the center of the plaza\" is a relative clause and \"plaza\" cannot govern the verb. So the singular \"comes\" (B) is correct. \"Come\" (A) is the plural form and wrongly agrees with the nearby \"plaza.\" \"Coming\" (C) is a participle that cannot serve as the main verb alone. \"To come\" (D) is an infinitive and likewise cannot be the sentence's main verb." },
  { id: "t12rw2h-15", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The editor was prized for her ______ — for trimming every sentence to its leanest, most forceful form.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economy", "verbosity", "hesitation", "carelessness"], correct: 0, explanation: "The editor is prized for \"trimming every sentence to its leanest, most forceful form,\" so the blank names a skill of using as few words as possible. \"Economy\" (A) means sparing, efficient use of words, exactly matching the lean trimming. \"Verbosity\" (B) means using too many words, the opposite of trimming. \"Hesitation\" (C) means holding back uncertainly, which is not a praised editorial skill here. \"Carelessness\" (D) means lack of attention, the opposite of disciplined, deliberate trimming." },
  { id: "t12rw2h-16", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author begins by admitting that early electric cars were slow and short-ranged, then argues that those very shortcomings forced the battery breakthroughs that made today's models practical.", prompt: "Which choice best describes the text's reasoning?", type: "mcq", choices: ["It recasts an early weakness as the spur for later strengths.", "It denies that early electric cars had any flaws.", "It claims electric cars never improved.", "It lists car prices across the decades."], correct: 0, explanation: "The author admits early electric cars were \"slow and short-ranged,\" then argues \"those very shortcomings forced the battery breakthroughs\" behind today's models, recasting a weakness as the spur for later strengths, which choice A states. Choice B says the author denies the cars had \"any flaws,\" contradicting the admitted shortcomings. Choice C says electric cars \"never improved,\" contradicting the breakthroughs that made today's models practical. Choice D says the text \"lists car prices,\" a topic it never mentions." },
  { id: "t12rw2h-17", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having rehearsed for months in a small studio ______ the cellist found the vast concert hall unexpectedly intimidating.", prompt: "Which choice avoids a dangling modifier and conforms to Standard English?", type: "mcq", choices: ["the vast concert hall felt intimidating", "the cellist found the vast concert hall intimidating", "intimidating was the vast concert hall", "it felt intimidating, the concert hall"], correct: 1, explanation: "Rule: an introductory participial phrase must modify the noun that immediately follows it. \"Having rehearsed for months in a small studio\" describes a person, the cellist, so the cellist must come right after the comma. Only choice B does this: \"the cellist found the vast concert hall intimidating.\" Choice A places \"the vast concert hall\" after the modifier, illogically saying the hall rehearsed. Choice C's \"intimidating was the vast concert hall\" again makes the hall the thing that rehearsed. Choice D's \"it felt intimidating\" leaves the modifier attached to \"it,\" creating a dangling modifier with no clear rehearser." },
  { id: "t12rw2h-18", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine cleared the virus rapidly in cell cultures. ______, its protection in living patients proved weaker and shorter-lasting.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "In patients, however", "For this reason", "Similarly"], correct: 1, explanation: "The vaccine \"cleared the virus rapidly in cell cultures\" (strong result) but its protection \"in living patients proved weaker\" (weaker result), so a contrast transition is needed. \"In patients, however\" (B) signals that opposition and fits. \"Consequently\" (A) marks a result, but the weaker protection is not caused by the strong culture results. \"For this reason\" (C) likewise marks a result and fails the same way. \"Similarly\" (D) marks agreement, the opposite of the contrast between strong and weak outcomes." },
  { id: "t12rw2h-19", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic admired the symphony's ______ design, noting how a four-note motif from the opening returns, disguised, in every movement.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["cohesive", "fragmented", "aimless", "chaotic"], correct: 0, explanation: "A four-note motif that \"returns, disguised, in every movement\" ties the whole symphony together, so the design is unified. \"Cohesive\" (A) means well-unified and holding together, exactly matching the recurring motif. \"Fragmented\" (B) means broken into disconnected parts, the opposite of a unifying motif. \"Aimless\" (C) means lacking direction, contradicting a deliberate design the critic praises. \"Chaotic\" (D) means disordered, again the opposite of the orderly unity the motif creates." },
  { id: "t12rw2h-20", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Across five schools, those that added a morning reading block saw test scores climb by an average of 14%, while those that kept their usual schedule saw essentially no change.", prompt: "Which claim is best supported by the data?", type: "mcq", choices: ["Adding a morning reading block was associated with higher scores.", "Keeping the usual schedule raised scores the most.", "Reading blocks had no relationship to scores.", "All five schools kept the same schedule."], correct: 0, explanation: "The data show schools that added a morning reading block saw scores \"climb by an average of 14%,\" while those keeping the usual schedule saw \"essentially no change,\" so the reading block is associated with higher scores, supporting choice A. Choice B says keeping the usual schedule \"raised scores the most,\" reversing the result, since those schools saw no change. Choice C says reading blocks had \"no relationship to scores,\" denying the 14% gain. Choice D says \"all five schools kept the same schedule,\" contradicting that some added a reading block." },
  { id: "t12rw2h-21", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The inventor's early sketches — rough, smudged, and barely labeled ______ already hinted at the machine that would transform the industry.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["sketches —", "sketches,", "sketches", "sketches;"], correct: 0, explanation: "Rule: punctuation that sets off a nonessential interrupter must be matched at both ends. The description \"rough, smudged, and barely labeled\" is opened by a dash after \"sketches,\" so it must be closed by a dash too, making \"sketches —\" (A) correct. A comma (B) cannot close a dash, mismatching the pair. No punctuation (C) leaves the interrupter unclosed. A semicolon (D) cannot pair with a dash and would also wrongly require two independent clauses." },
  { id: "t12rw2h-22", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The board dismissed the engineer's warning as ______, only to see the very failure she had predicted occur the following winter.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["overcautious", "prophetic", "accurate", "justified"], correct: 0, explanation: "The board \"dismissed\" the warning, so the blank must capture a dismissive, negative judgment of it; the irony is that the warning later proved right. \"Overcautious\" (A) means excessively worried, a dismissive label that fits how the board wrongly judged the warning. \"Prophetic\" (B) means accurately predicting the future, which praises the warning rather than dismissing it. \"Accurate\" (C) means correct, again a positive judgment the board did not make. \"Justified\" (D) means well-founded, which would mean the board agreed with the warning, contradicting \"dismissed.\"" },
  { id: "t12rw2h-23", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "One archaeologist argues the settlement was abandoned because of a prolonged drought; another insists the cause was conflict with neighboring groups. A third suggests the drought intensified the conflict, so the two causes worked together.", prompt: "Which choice best describes the third archaeologist's position?", type: "mcq", choices: ["Drought and conflict combined to cause the abandonment.", "Neither drought nor conflict played any role.", "Only drought mattered.", "The settlement was never abandoned."], correct: 0, explanation: "The third archaeologist \"suggests the drought intensified the conflict, so the two causes worked together,\" which choice A restates as drought and conflict combining to cause the abandonment. Choice B says \"neither drought nor conflict played any role,\" contradicting that both worked together. Choice C says \"only drought mattered,\" naming a single cause when the third archaeologist names two. Choice D says \"the settlement was never abandoned,\" contradicting the abandonment all three archaeologists are explaining." },
  { id: "t12rw2h-24", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The crew rerouted the pipeline ______ the original path crossed an unstable fault line.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["pipeline, the", "pipeline; the", "pipeline the", "pipeline: the"], correct: 1, explanation: "Rule: two independent clauses with no coordinating conjunction must be joined by a semicolon. \"The crew rerouted the pipeline\" and \"the original path crossed an unstable fault line\" are both complete clauses, so \"pipeline; the\" (B) is correct. \"Pipeline, the\" (A) uses only a comma, creating a comma splice. \"Pipeline the\" (C) has no punctuation, creating a run-on. \"Pipeline: the\" (D) uses a colon, which wrongly signals a list or explanation rather than joining two independent clauses." },
  { id: "t12rw2h-25", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The author wants to stress that the reform's gains went mainly to large firms. ______, big corporations received generous tax breaks while small businesses got almost nothing.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Specifically", "In contrast", "Nevertheless", "Otherwise"], correct: 0, explanation: "The first sentence makes a general point (the reform's gains went mainly to large firms) and the second gives a concrete illustration (big corporations got tax breaks while small businesses got almost nothing), so an illustrating transition is needed. \"Specifically\" (A) introduces that detailed example and fits. \"In contrast\" (B) signals opposition, but the example supports rather than opposes the point. \"Nevertheless\" (C) signals concession, again not a reinforcing example. \"Otherwise\" (D) introduces an alternative condition, not an illustration." },
  { id: "t12rw2h-26", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than tying every thread together, the filmmaker leaves several subplots ______, trusting viewers to imagine their outcomes.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unresolved", "concluded", "obvious", "finished"], correct: 0, explanation: "\"Rather than tying every thread together,\" the filmmaker leaves outcomes for viewers to imagine, so the subplots are left open and unfinished. \"Unresolved\" (A) means not brought to a conclusion, exactly matching leaving outcomes to the imagination. \"Concluded\" (B) means brought to an end, the opposite of leaving threads untied. \"Finished\" (C) likewise means completed, contradicting the open endings. \"Obvious\" (D) means easily seen, which does not describe outcomes left for viewers to imagine." },
  { id: "t12rw2h-27", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her data came from only one growing season, but she contends that the effect she measured was so strong and consistent that it warrants a multiyear study.", prompt: "Which choice best describes the author's reasoning?", type: "mcq", choices: ["She admits a limitation while defending the finding's importance.", "She claims her study had no weaknesses.", "She abandons her finding entirely.", "She argues that no further study is needed."], correct: 0, explanation: "The author \"concedes that her data came from only one growing season\" (a limitation) but \"contends that the effect... warrants a multiyear study\" (defending its importance), which choice A captures as admitting a limitation while defending the finding. Choice B says she claims \"no weaknesses,\" contradicting the conceded single-season limit. Choice C says she \"abandons her finding entirely,\" contradicting her defense of its strength. Choice D says \"no further study is needed,\" contradicting her explicit call for a multiyear study." },
];

// ─────────────────────── PRACTICE TEST 12 · MATH M1 (22) ─────────────────────
const T12_M_M1: SatQuestion[] = [
  { id: "t12m1-1", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x + 8 = 43, what is the value of x?", type: "grid", gridAnswers: ["7"], explanation: "Goal: solve for x. Subtract 8 from both sides: 5x = 35. Divide by 5: x = 7. Check: 5(7) + 8 = 35 + 8 = 43, which matches the equation. A common trap is dividing 43 by 5 before subtracting the 8." },
  { id: "t12m1-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A recipe uses 2 cups of rice for every 5 servings. How many cups are needed for 15 servings?", type: "mcq", choices: ["6", "5", "7", "8"], correct: 0, explanation: "Goal: scale the ratio to 15 servings. The rice-per-serving rate is 2/5 = 0.4 cup. Multiply by 15 servings: 0.4 × 15 = 6 cups. Equivalently, 15 servings is 3 times 5 servings, so 2 × 3 = 6 cups. Check: 6 cups for 15 servings gives 6/15 = 2/5, the original ratio. The trap is using 2 × 15 = 30 without dividing by 5." },
  { id: "t12m1-3", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 3x² − 4, what is the value of f(2)?", type: "mcq", choices: ["8", "2", "20", "5"], correct: 0, explanation: "Goal: evaluate f at x = 2. Substitute: f(2) = 3(2²) − 4. By order of operations, compute the square first: 2² = 4, so 3 × 4 = 12. Then 12 − 4 = 8. Check: re-reading f(x) = 3x² − 4 with x = 2 confirms 3·4 − 4 = 8. The trap is squaring after multiplying, giving (3·2)² − 4 = 36 − 4 = 32." },
  { id: "t12m1-4", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a diameter of 18. What is its radius?", type: "grid", gridAnswers: ["9"], explanation: "Goal: find the radius from the diameter. The radius is half the diameter: r = 18 ÷ 2 = 9. Check: 2 × 9 = 18, the given diameter. The trap is doubling instead of halving." },
  { id: "t12m1-5", section: "math", domain: "Algebra", difficulty: "med", prompt: "The line y = 3x + 2 passes through the point (4, k). What is the value of k?", type: "grid", gridAnswers: ["14"], explanation: "Goal: find k, the y-value when x = 4. Substitute x = 4: k = 3(4) + 2. Multiply: 3 × 4 = 12. Add: 12 + 2 = 14. The trap is adding before multiplying, giving 3(6) = 18." },
  { id: "t12m1-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "The mean of the numbers 6, 10, and x is 9. What is the value of x?", type: "mcq", choices: ["11", "9", "8", "13"], correct: 0, explanation: "Goal: find x given the mean is 9. The sum of three numbers equals 3 × 9 = 27. So 6 + 10 + x = 27, meaning 16 + x = 27, so x = 11. Check: (6 + 10 + 11)/3 = 27/3 = 9. The trap is forgetting to multiply the mean by 3." },
  { id: "t12m1-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x + 7 = 31, what is the value of x?", type: "mcq", choices: ["6", "9", "24", "7"], correct: 0, explanation: "Goal: solve for x. Subtract 7: 4x = 24. Divide by 4: x = 6. Check: 4(6) + 7 = 24 + 7 = 31. The trap is choosing 24, which is 4x rather than x." },
  { id: "t12m1-8", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "What is the sum of the solutions to x² − 9x + 20 = 0?", type: "grid", gridAnswers: ["9"], explanation: "Goal: add the two roots. Factoring, x² − 9x + 20 = (x − 4)(x − 5), so the roots are 4 and 5. Their sum is 4 + 5 = 9. This also equals −b/a = −(−9)/1 = 9. The trap is reporting the product, 20, instead of the sum." },
  { id: "t12m1-9", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A book's price increased from $40 to $50. What was the percent increase?", type: "mcq", choices: ["25%", "20%", "10%", "125%"], correct: 0, explanation: "Goal: find the percent increase. The increase is 50 − 40 = 10. Percent increase = increase ÷ original price = 10/40 = 0.25 = 25%. Check: 25% of $40 is $10, and $40 + $10 = $50, the new price. The trap is dividing by the new price (10/50 = 20%) instead of the original." },
  { id: "t12m1-10", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "Two angles of a triangle measure 45° and 85°. What is the measure, in degrees, of the third angle?", type: "grid", gridAnswers: ["50"], explanation: "Goal: find the third angle. The angles of a triangle sum to 180°. So the third angle is 180 − 45 − 85 = 50°. Check: 45 + 85 + 50 = 180. The trap is using 360° instead of 180°." },
  { id: "t12m1-11", section: "math", domain: "Algebra", difficulty: "med", prompt: "A plumber charges a $40 service fee plus $30 per hour. Which equation gives the cost C for h hours?", type: "mcq", choices: ["C = 30h + 40", "C = 40h + 30", "C = 70h", "C = 30h − 40"], correct: 0, explanation: "Goal: model the cost. The flat fee $40 does not depend on hours, so it is the constant; the $30 per hour multiplies the hours h. This gives C = 30h + 40 (A). Check: for h = 2 hours, C = 30(2) + 40 = 100, which equals the $40 fee plus 2 × $30 = $60. The trap is swapping the rate and fee to get 40h + 30, which would wrongly charge $40 per hour and a $30 fee." },
  { id: "t12m1-12", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If (x + 5)(x − 3) = x² + bx − 15, what is the value of b?", type: "grid", gridAnswers: ["2"], explanation: "Goal: find b after expanding. Use FOIL: (x + 5)(x − 3) = x·x + x·(−3) + 5·x + 5·(−3) = x² − 3x + 5x − 15 = x² + 2x − 15. Matching to x² + bx − 15 gives b = 2. Check: −3 + 5 = 2, the coefficient of x. The trap is adding 5 and 3 to get 8 instead of combining the like terms −3x and +5x." },
  { id: "t12m1-13", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "In a survey of 300 people, 40% preferred coffee. How many people preferred coffee?", type: "mcq", choices: ["120", "40", "150", "75"], correct: 0, explanation: "Goal: find 40% of 300. Convert the percent to a decimal: 40% = 0.40. Multiply: 0.40 × 300 = 120. Check: 10% of 300 is 30, so 40% is 4 × 30 = 120; this is just under half of 300, consistent with 40%. The trap is reading 40 as the count instead of computing 40 percent of 300." },
  { id: "t12m1-14", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5(x − 1) = 3x + 7, what is the value of x?", type: "mcq", choices: ["6", "4", "3", "8"], correct: 0, explanation: "Goal: solve for x. Distribute: 5x − 5 = 3x + 7. Subtract 3x: 2x − 5 = 7. Add 5: 2x = 12. Divide: x = 6. Check: 5(6 − 1) = 25 and 3(6) + 7 = 25. The trap is forgetting to distribute the 5 to the −1." },
  { id: "t12m1-15", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A rectangle has length 12 and width 5. What is its perimeter?", type: "mcq", choices: ["34", "60", "17", "24"], correct: 0, explanation: "Goal: find the perimeter. Use P = 2(length + width) = 2(12 + 5) = 2(17) = 34. Check: adding all four sides, 12 + 5 + 12 + 5 = 34. The trap is computing the area (12 × 5 = 60) instead of the perimeter." },
  { id: "t12m1-16", section: "math", domain: "Advanced Math", difficulty: "hard", prompt: "If 3^(x−1) = 27, what is the value of x?", type: "grid", gridAnswers: ["4"], explanation: "Goal: solve the exponential equation. Write 27 as a power of 3: 27 = 3³. So 3^(x−1) = 3³ means x − 1 = 3, giving x = 4. Check: 3^(4−1) = 3³ = 27. The trap is solving x − 1 = 27 and getting 28." },
  { id: "t12m1-17", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A map uses a scale of 1 inch = 30 miles. Two towns are 5 inches apart on the map. How many miles apart are they?", type: "mcq", choices: ["150", "120", "180", "35"], correct: 0, explanation: "Goal: convert map inches to miles. Set up the proportion 1 inch / 30 miles = 5 inches / d miles, so d = 5 × 30 = 150 miles. Check: 150 miles ÷ 30 miles per inch = 5 inches, matching the map distance. The trap is adding (30 + 5 = 35) instead of multiplying by the scale." },
  { id: "t12m1-18", section: "math", domain: "Algebra", difficulty: "med", prompt: "The slope of the line through (2, 3) and (6, 15) is what value?", type: "grid", gridAnswers: ["3"], explanation: "Goal: find the slope. Use rise over run: (15 − 3)/(6 − 2) = 12/4 = 3. Check: from (2,3) moving right 4 and up 12 reaches (6,15). The trap is inverting to (6−2)/(15−3) = 1/3." },
  { id: "t12m1-19", section: "math", domain: "Advanced Math", difficulty: "med", prompt: "If f(x) = 4x − 5, what value of x makes f(x) = 23?", type: "mcq", choices: ["7", "6", "8", "5"], correct: 0, explanation: "Goal: solve 4x − 5 = 23. Add 5: 4x = 28. Divide by 4: x = 7. Check: 4(7) − 5 = 28 − 5 = 23. The trap is dividing 23 by 4 before adding the 5." },
  { id: "t12m1-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "med", prompt: "A circle has a radius of 8. What is its area, in terms of π?", type: "mcq", choices: ["64π", "16π", "8π", "32π"], correct: 0, explanation: "Goal: find the area. Use A = πr² = π(8²) = π(64) = 64π. Check: the radius squared, 8² = 64, gives the coefficient directly. The trap is using the circumference formula 2πr = 2π(8) = 16π, or doubling instead of squaring the radius." },
  { id: "t12m1-21", section: "math", domain: "Algebra", difficulty: "med", prompt: "If 5x − y = 17 and y = 3, what is the value of x?", type: "mcq", choices: ["4", "3", "5", "7"], correct: 0, explanation: "Goal: solve for x. Substitute y = 3: 5x − 3 = 17. Add 3: 5x = 20. Divide: x = 4. Check: 5(4) − 3 = 20 − 3 = 17. The trap is subtracting 3 instead of adding it when isolating 5x." },
  { id: "t12m1-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "med", prompt: "A worker earns $22 per hour. How much does the worker earn for a 30-hour week?", type: "grid", gridAnswers: ["660"], explanation: "Goal: find total weekly pay. Multiply the hourly rate by the hours: 22 × 30 = 660 dollars. Break it down: 22 × 3 = 66, then ×10 = 660. The trap is adding 22 + 30 = 52 instead of multiplying." },
];

// ─────────────────────── PRACTICE TEST 12 · MATH M2 easy (22) ────────────────
const T12_M_M2E: SatQuestion[] = [
  { id: "t12m2e-1", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x + 6 = 14, what is the value of x?", type: "grid", gridAnswers: ["8"], explanation: "Goal: solve for x. Subtract 6 from both sides: x = 14 − 6 = 8. Check: 8 + 6 = 14. The trap is adding 6 instead of subtracting it." },
  { id: "t12m2e-2", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 20% of 80?", type: "mcq", choices: ["16", "20", "60", "100"], correct: 0, explanation: "Goal: find 20% of 80. Convert 20% to 0.20 and multiply: 0.20 × 80 = 16. Check: 10% of 80 is 8, so 20% is 16. The trap is choosing 20, the percent itself." },
  { id: "t12m2e-3", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A rectangle has a length of 9 and a width of 4. What is its area?", type: "grid", gridAnswers: ["36"], explanation: "Goal: find the area. Multiply length by width: A = 9 × 4 = 36. Check: a 9-by-4 grid contains 36 unit squares. The trap is computing the perimeter, 2(9 + 4) = 26, instead of the area." },
  { id: "t12m2e-4", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 8x = 56, what is the value of x?", type: "mcq", choices: ["7", "8", "48", "64"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 8: x = 56 ÷ 8 = 7. Check: 8 × 7 = 56. The trap is subtracting (56 − 8 = 48) instead of dividing." },
  { id: "t12m2e-5", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 5² − 4?", type: "grid", gridAnswers: ["21"], explanation: "Goal: evaluate the expression. By order of operations, square first: 5² = 25. Then subtract: 25 − 4 = 21. Check: 25 − 4 = 21. The trap is subtracting before squaring, giving (5 − 4)² = 1² = 1." },
  { id: "t12m2e-6", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A team won 8 of its 12 games. What fraction of its games did it win?", type: "mcq", choices: ["2/3", "8/12", "1/2", "3/4"], correct: 0, explanation: "Goal: write the win fraction in lowest terms. 8/12 divides top and bottom by 4 to give 2/3. Check: 2/3 of 12 is 8. While 8/12 is equal, the simplest form 2/3 is the intended answer." },
  { id: "t12m2e-7", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x − 5 = 9, what is the value of x?", type: "grid", gridAnswers: ["14"], explanation: "Goal: solve for x. Add 5 to both sides: x = 9 + 5 = 14. Check: 14 − 5 = 9. The trap is subtracting 5 to get 4." },
  { id: "t12m2e-8", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is the average of 12, 18, and 30?", type: "mcq", choices: ["20", "30", "15", "60"], correct: 0, explanation: "Goal: find the mean. Add the values: 12 + 18 + 30 = 60. Divide by the count 3: 60 ÷ 3 = 20. Check: 20 × 3 = 60, the original sum. The trap is reporting the sum, 60, instead of the average." },
  { id: "t12m2e-9", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A square has a side length of 7. What is its perimeter?", type: "grid", gridAnswers: ["28"], explanation: "Goal: find the perimeter. A square has four equal sides: P = 4 × 7 = 28. Check: 7 + 7 + 7 + 7 = 28. The trap is finding the area, 7² = 49, instead of the perimeter." },
  { id: "t12m2e-10", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 3x + 2 = 17, what is the value of x?", type: "mcq", choices: ["5", "6", "15", "4"], correct: 0, explanation: "Goal: solve for x. Subtract 2: 3x = 15. Divide by 3: x = 5. Check: 3(5) + 2 = 17. The trap is choosing 15, which is 3x, not x." },
  { id: "t12m2e-11", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "If f(x) = x + 9, what is f(6)?", type: "grid", gridAnswers: ["15"], explanation: "Goal: evaluate f at x = 6. Substitute x = 6 into f(x) = x + 9: f(6) = 6 + 9 = 15. Check: 6 + 9 = 15. The trap is multiplying 6 × 9 = 54 instead of adding." },
  { id: "t12m2e-12", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A store sells 5 notebooks for $10. How much do 8 notebooks cost?", type: "mcq", choices: ["$16", "$13", "$18", "$15"], correct: 0, explanation: "Goal: find the cost of 8 notebooks. First find the unit price: $10 ÷ 5 = $2 per notebook. Then 8 × $2 = $16. Check: 5 notebooks at $2 is $10, matching the given price. The trap is adding 3 dollars for 3 more notebooks (giving $13) instead of using the $2 unit price." },
  { id: "t12m2e-13", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 6x = 48, what is the value of x?", type: "mcq", choices: ["8", "7", "6", "42"], correct: 0, explanation: "Goal: solve for x. Divide both sides by 6: x = 48 ÷ 6 = 8. Check: 6 × 8 = 48. The trap is subtracting (48 − 6 = 42) instead of dividing." },
  { id: "t12m2e-14", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A triangle has a base of 8 and a height of 5. What is its area?", type: "grid", gridAnswers: ["20"], explanation: "Goal: find the triangle's area. Use A = (1/2)(base)(height) = (1/2)(8)(5) = (1/2)(40) = 20. Check: a triangle is half of the 8-by-5 rectangle of area 40, so 40 ÷ 2 = 20. The trap is forgetting the 1/2 factor and getting 40." },
  { id: "t12m2e-15", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "What is 25% of 64?", type: "mcq", choices: ["16", "25", "32", "8"], correct: 0, explanation: "Goal: find 25% of 64. Since 25% is one-fourth, divide by 4: 64 ÷ 4 = 16. Check: 16 × 4 = 64. The trap is choosing 25, the percent itself." },
  { id: "t12m2e-16", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If x/3 = 7, what is the value of x?", type: "grid", gridAnswers: ["21"], explanation: "Goal: solve for x. The equation x/3 = 7 means x divided by 3 equals 7, so multiply both sides by 3: x = 7 × 3 = 21. Check: 21 ÷ 3 = 7, the original equation. The trap is dividing (7 ÷ 3) instead of multiplying by 3." },
  { id: "t12m2e-17", section: "math", domain: "Advanced Math", difficulty: "easy", prompt: "What is the value of 3³?", type: "mcq", choices: ["27", "9", "6", "12"], correct: 0, explanation: "Goal: evaluate 3 cubed. The exponent 3 means multiply 3 by itself three times: 3 × 3 × 3 = 9 × 3 = 27. Check: 3² = 9, then 9 × 3 = 27. The trap is computing 3 × 3 = 9 and stopping at only two factors, or multiplying 3 × 3 = 9." },
  { id: "t12m2e-18", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A car travels 90 miles in 3 hours. What is its average speed in miles per hour?", type: "mcq", choices: ["30", "90", "270", "45"], correct: 0, explanation: "Goal: find average speed. Speed equals distance divided by time: 90 ÷ 3 = 30 mph. Check: 30 mph × 3 hours = 90 miles, the given distance. The trap is multiplying (90 × 3 = 270) instead of dividing." },
  { id: "t12m2e-19", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If 4x − 8 = 12, what is the value of x?", type: "grid", gridAnswers: ["5"], explanation: "Goal: solve for x. Add 8 to both sides: 4x = 20. Divide by 4: x = 5. Check: 4(5) − 8 = 20 − 8 = 12. The trap is dividing 12 by 4 before adding the 8." },
  { id: "t12m2e-20", section: "math", domain: "Geometry and Trigonometry", difficulty: "easy", prompt: "A circle has a radius of 9. What is its diameter?", type: "mcq", choices: ["18", "9", "4.5", "81"], correct: 0, explanation: "Goal: find the diameter. The diameter is twice the radius: 2 × 9 = 18. The trap is halving (9 ÷ 2 = 4.5) instead of doubling." },
  { id: "t12m2e-21", section: "math", domain: "Algebra", difficulty: "easy", prompt: "If y = 3x and x = 5, what is the value of y?", type: "mcq", choices: ["15", "8", "2", "5"], correct: 0, explanation: "Goal: find y. Substitute x = 5 into y = 3x: y = 3 × 5 = 15. Check: 3 times 5 is 15. The trap is adding (3 + 5 = 8) instead of multiplying." },
  { id: "t12m2e-22", section: "math", domain: "Problem-Solving and Data Analysis", difficulty: "easy", prompt: "A jar holds 6 green and 9 yellow marbles. What fraction of the marbles are green?", type: "mcq", choices: ["2/5", "6/9", "1/2", "3/5"], correct: 0, explanation: "Goal: find the fraction of green marbles. Total marbles = 6 + 9 = 15. Green fraction = 6/15, which simplifies to 2/5. The trap is writing 6/9, comparing green to yellow rather than to the total." },
];

